// TRIM mean-response calibration for the screened 900 mbar He/CF4 sample.
// Frozen dense fit: 300 independent events at each of 28 energies per ion.
// See docs/screening-technical-note.md for provenance and qualified scope.
#ifndef CYGNO_SCREENING_RESPONSE_HH
#define CYGNO_SCREENING_RESPONSE_HH
#include "G4Event.hh"
#include "G4PrimaryVertex.hh"
#include "G4PrimaryParticle.hh"
#include "G4SystemOfUnits.hh"
#include "G4Exception.hh"
#include <algorithm>
#include <cmath>

inline G4double CYGNOScreeningResponseGain(const G4Event* event, G4double response)
{
  // Calibration is defined for single-primary, contained ion calibration runs.
  // Other sources retain the existing local TRIM derivative prescription.
  if (event->GetNumberOfPrimaryVertex() != 1) return 1.;
  const auto* vertex = event->GetPrimaryVertex();
  if (vertex->GetNumberOfParticle() != 1) return 1.;
  const auto* primary = vertex->GetPrimary();
  static const G4int pdgs[] = {2212, 1000020040, 1000060120, 1000080160, 1000090190};
  const auto* found = std::find(pdgs, pdgs+5, primary->GetPDGcode());
  if (found == pdgs+5) return 1.;
  const G4double energy = primary->GetKineticEnergy()/keV;
  if (energy < 0.25 || energy > 1000.) return 1.;
  static const G4double energies[] = {0.25, 0.3532041857285485, 0.49901278726466819, 0.70501362077580221, 0.99605504741461182, 1, 1.4072432478515551, 1.9881768219176268, 2.8089295018791547, 3.9685026299204984, 5.6067669598506935, 7.9213342344951743, 10, 11.191393632714178, 15.811388300841895, 22.338594120147032, 31.560339786108297, 44.588976461874815, 62.996052494743637, 89.001877702075262, 100, 125.74334296829353, 177.65230025560686, 250.99014421834093, 354.6030780581205, 500.98916576942156, 707.80588141765315, 1000};
  static const G4double alpha[5][28] = {
    {1.1880473497045152, 1.2458301782335346, 1.2826721985827465, 1.2481577553967795, 1.2014770103007277, 1.2196056487969416, 1.1747257000139655, 1.1780707842258293, 1.1629302051176316, 1.1539227082563548, 1.1609211895892459, 1.1470507197302457, 1.1316414626852129, 1.1335516979768008, 1.1337490718656253, 1.1247296921565844, 1.1066956958542027, 1.1116096904545669, 1.0994933138293512, 1.0946881983645538, 1.1025227163690128, 1.0917494239480474, 1.0912557495147552, 1.0765637928547989, 1.0815211941689389, 1.0855404669621298, 1.0800064089403054, 1.0756500394757214}, // H1
    {1.5294841701655906, 1.636423190560613, 1.7044161797191402, 1.7937427634592633, 1.8669512431675748, 1.8174815293147539, 1.8506629649331134, 1.8569622534826804, 1.7743931712829064, 1.7702946104244057, 1.6622834310331964, 1.5916495181224557, 1.5460645035279905, 1.5099639673784333, 1.4701916417338781, 1.4153608115460561, 1.3868003219186582, 1.3388964540733757, 1.3067969859273363, 1.2641517107168971, 1.279108515030585, 1.2390123714335364, 1.2189972950194599, 1.2102842280667556, 1.1910746141636261, 1.17167158595412, 1.1610166212642266, 1.1504807463715045}, // He4
    {1.3642966793666365, 1.4549708233310279, 1.5713431311342156, 1.5985108591925237, 1.6430010398067183, 1.6787152574746464, 1.7012676174848784, 1.7764858999130895, 1.75062416442915, 1.7898220624700034, 1.8176375694990994, 1.8095122216274169, 1.7816636711708058, 1.7867757550724235, 1.6997452521563063, 1.6631390963743629, 1.5942124830524127, 1.5253377186208408, 1.4668223031143075, 1.4115191417268755, 1.4035069161735312, 1.3624385411250886, 1.2974020960450758, 1.2703482620160513, 1.2428843129382301, 1.2022174947275788, 1.1887196997704952, 1.1688852599941655}, // C12
    {1.3078931858230611, 1.3666555487898759, 1.4547984807770447, 1.515658421949057, 1.5780767018297304, 1.5602667919466628, 1.666568687948679, 1.7201488311877322, 1.748892656405185, 1.7868053764617393, 1.7955141264927859, 1.8224078410151714, 1.8366849712122379, 1.8386313220251562, 1.791759516840788, 1.7754400576648999, 1.6999205552856727, 1.6517700282688952, 1.57615801757281, 1.5210826842852165, 1.4973327333205146, 1.465165945576945, 1.3988179054632184, 1.341884114445371, 1.2942782907822914, 1.2674059095659655, 1.2294446529657095, 1.2048232862209334}, // O16
    {1.1672878058240781, 1.2748165244368486, 1.3452221365800949, 1.3907354488033006, 1.472085002533615, 1.4645705941582332, 1.5577564302747049, 1.5924919043497738, 1.6435990183936262, 1.6905646563583223, 1.7528548932588028, 1.7429974814792117, 1.7796137663555673, 1.8039654931194711, 1.7722510361853754, 1.7515943557178784, 1.7472960327018412, 1.6905143825999513, 1.6258852823766803, 1.5393025273145764, 1.5245802011751568, 1.4871821045066518, 1.4326658969262747, 1.3972085757257249, 1.3357119376837068, 1.2876586886244088, 1.2490219139063397, 1.2246118762463207}, // F19
  };
  const auto* table = alpha[found-pdgs];
  const auto upper = std::upper_bound(energies, energies+28, energy);
  const auto j = std::min<std::ptrdiff_t>(27, std::max<std::ptrdiff_t>(1, upper-energies));
  const auto t = std::log(energy/energies[j-1])/std::log(energies[j]/energies[j-1]);
  const auto parameter = std::exp((1.-t)*std::log(table[j-1])+t*std::log(table[j]));
  const auto fraction = response/energy;
  if (!std::isfinite(fraction) || fraction < 0. || fraction > 1.) {
    G4Exception("CYGNOScreeningResponseGain", "ScreeningResponseBudget",
                FatalException, "Custom response outside primary energy budget");
    return 1.;
  }
  if (fraction == 0. || fraction == 1.) return 1.;
  return -std::expm1(parameter*std::log1p(-fraction))/fraction;
}
#endif
